/* HEXA BATTLEGROUNDS upgrade2 — PART 5 OF 22. For databases that already ran supabase/upgrade (match phases); Run in order. Safe to re-run. */ create or replace function _set_match_phase(p_arena uuid, p_phase int) returns void language plpgsql as $$ declare a arenas; e events; v_next timestamptz; v_sched text[]; v_min int; begin select * into a from arenas where id = p_arena for update; select * into e from events where id = a.event_id; p_phase := greatest(0, least(5, p_phase)); if p_phase < 4 and _cfg(a.event_id, 'auto_pacing') = 1 and a.play_started_at is not null then v_sched := string_to_array(_cfg_text(a.event_id, 'phase_schedule'), ','); begin v_min := nullif(trim(v_sched[p_phase + 1]), '')::int; exception when others then v_min := null; end; if v_min is not null then v_next := greatest(now() + interval '5 seconds', a.play_started_at + make_interval(mins => v_min)); end if; end if; update arenas set match_phase = p_phase, phase_started_at = now(), phase_next_at = v_next, zone_hold = false, overlay = overlay || jsonb_build_object('match', jsonb_build_object( 'phase', p_phase, 'started_at', now(), 'next_at', v_next, 'duel_phase', _cfg(a.event_id, 'duel_phase'), 'zone_target', _phase_zone_target(p_phase))) where id = p_arena; if a.match_phase is distinct from p_phase or a.phase_started_at is null then perform _feed(p_arena, 'phase.started', jsonb_build_object('phase', p_phase)); end if; perform _zone_publish(p_arena); perform _ping_arena(p_arena, 'phase'); end $$; create or replace function captain_move(p_token text, p_location text) returns jsonb language plpgsql security definer set search_path = public as $$ declare p players; t teams; a arenas; l locations; v_secs numeric; cur float8[]; d float8; begin p := _auth_captain(p_token); select * into t from teams where id = p.team_id for update; select * into a from arenas where id = t.arena_id; if a.phase <> 'play' then raise exception 'NO_MOVES_NOW'; end if; if t.state = 'recovery' then raise exception 'BUSY'; end if; if exists (select 1 from mission_instances where team_id = t.id and status = 'active' and kind = 'battle') then raise exception 'IN_BATTLE'; end if; select * into l from locations where id = p_location; if l.id is null or l.kind = 'start' or not l.enabled then raise exception 'BAD_LOCATION'; end if; if l.id = t.location_id and t.state = 'idle' then raise exception 'ALREADY_HERE'; end if; cur := _team_xy(t); d := sqrt((l.x - cur[1]) ^ 2 + (l.y - cur[2]) ^ 2); if not t.dropped then v_secs := _cfg(t.event_id, 'drop_seconds'); else v_secs := greatest(1, round((d / (_cfg(t.event_id, 'move_speed') / 1000.0))::numeric, 1)); end if; update mission_instances set status = 'cancelled' where team_id = t.id and status = 'active' and kind in ('mission', 'relay', 'airdrop') and sync_round_id is null; update teams set state = 'traveling', travel_from = location_id, travel_to = l.id, travel_started_at = now(), travel_arrive_at = now() + _secs(v_secs), travel_fx = cur[1], travel_fy = cur[2], pos_x = cur[1], pos_y = cur[2], pos_at = now() where id = t.id; if t.jammed_until is null or t.jammed_until < now() then perform _feed(t.arena_id, 'squad.movement.started', jsonb_build_object('team', t.number, 'from', t.location_id, 'to', l.id)); end if; perform _ping_team(t.id, 'move'); perform _ping_arena(t.arena_id, 'move'); return jsonb_build_object('arrive_at', now() + _secs(v_secs), 'seconds', v_secs); end $$; create or replace function captain_explore(p_token text) returns jsonb language plpgsql security definer set search_path = public as $$ declare p players; t teams; v_id uuid; begin p := _auth_captain(p_token); select * into t from teams where id = p.team_id for update; if (select phase from arenas where id = t.arena_id) <> 'play' then raise exception 'NO_MOVES_NOW'; end if; if t.state <> 'idle' then raise exception 'BUSY'; end if; if t.location_id is null then raise exception 'NOT_AT_LOCATION'; end if; if exists (select 1 from mission_instances where team_id = t.id and status = 'active' and kind <> 'battle') then raise exception 'MISSION_ACTIVE'; end if; if t.visit_missions >= _cfg(t.event_id, 'visit_missions') then raise exception 'AREA_EXHAUSTED'; end if; v_id := _start_location_mission(t.id); if v_id is null then raise exception 'NO_MISSIONS'; end if; return jsonb_build_object('instance', v_id); end $$; create or replace function captain_buy(p_token text, p_item text) returns jsonb language plpgsql security definer set search_path = public as $$ declare p players; t teams; l locations; it items; begin p := _auth_captain(p_token); select * into t from teams where id = p.team_id for update; select * into l from locations where id = t.location_id; if t.state <> 'idle' or l.id is null or not (l.tags && array['market', 'social']) then raise exception 'NO_MARKET_HERE'; end if; select * into it from items where id = p_item; if it.id is null or it.price <= 0 then raise exception 'BAD_ITEM'; end if; if 'social' = any(l.tags) and not ('market' = any(l.tags)) and it.kind not in ('intel', 'stealth', 'airdrop') then raise exception 'NOT_SOLD_HERE'; end if; if t.coins < it.price then raise exception 'NOT_ENOUGH_COINS'; end if; perform _apply(t.id, 'purchase', 0, -it.price, 0, 0, null, 'Bought ' || it.name); perform _add_item(t.id, p_item, 1); perform _ping_team(t.id, 'item'); return jsonb_build_object('bought', p_item); end $$;
